"""pacs-status-dashboard: builds the dashboards, Power BI kit and docs from the anonymised data in data/processed/.
python src/build.py"""
import sys, re, glob, warnings
from datetime import datetime
from pathlib import Path
import numpy as np, pandas as pd, openpyxl
warnings.filterwarnings("ignore")
ROOT = Path(__file__).resolve().parents[1]; PROC = ROOT / "data" / "processed"; sys.path.insert(0, str(Path(__file__).parent))
from scaffold import Project, PALETTE
CUR = pd.Timestamp("2025-03-31")   # a day-end on/after this date counts as 'current'
up = lambda s: s.astype(str).str.upper().str.strip(); tt = lambda s: s.astype(str).str.strip().str.title()

rd = lambda n: pd.read_csv(PROC / n)
sn, dpd, gd, gb, gg, sd, sb, sbn, wk, lg, mdm, mst, rz, rzr = [rd(n) for n in ["dayend_snapshots.csv", "dayend_progress_district.csv", "gap_district.csv", "gap_bands.csv", "gap_groups.csv", "sep2025_district.csv", "sep2025_branch.csv", "sep2025_bands.csv", "working_status_3dec2025.csv", "laggards_3dec2025.csv", "dayend_month_3dec2025_district.csv", "dayend_month_3dec2025_state.csv", "redzone_district.csv", "redzone_reasons.csv"]]
P = Project(ROOT, "pacs-status-dashboard", "PACS Status Dashboard: State A",
            "Operational status of all PACS on the e-PACS ERP: day-end currency, age of last entry, working and laggard PACS, the Sep-2025 district league and the Red Zone list.",
            banner="Illustrative data: names are pseudonymised and counts are rescaled. The reporting design, KPIs and method are real; the numbers are not.",
            footer="Anonymised portfolio edition. Do not use these figures for decisions.")
L, F0 = sn.iloc[-1], sn.iloc[0]; gs = gb[gb.measure == "Entry gap"].set_index("band").pacs; old = int(gs["181-365"] + gs[">365"])
k1 = P.kpi("PACS with a current day-end (5-Nov-2025)", L.current, "int", "PACS whose last day-end is on or after 31-Mar-2025", "Count of PACS", "SUM(dayend_snapshots[current])", "Source tracker", "cooperative registrar, Collector, development finance partner", home=True)
k2 = P.kpi("Current day-end %", 100 * L.current / L.total, "pct1", "Share of all PACS with a current day-end", "Current / Total", "DIVIDE(SUM(dayend_snapshots[current]), SUM(dayend_snapshots[total]))", "Source tracker", "cooperative registrar, Minister", tone="good", home=True)
k3 = P.kpi("Gain since 29-Sep-2025", L.current - F0.current, "int", "Increase in current-day-end PACS from the first to the last snapshot", "Latest - first", "MAX(dayend_snapshots[current]) - MIN(dayend_snapshots[current])", "Source tracker", "cooperative registrar")
k4 = P.kpi("Average day-end lag (days)", L.avg_gap_days, "dec1", "Mean days between the snapshot date and each PACS's last day-end", "Mean(snapshot - last day-end)", "AVERAGE(dayend_progress_district[avg_gap])", "Source tracker", "cooperative registrar, Collector", home=True)
k5 = P.kpi("Entry older than 180 days (6-Nov)", 100 * old / gs.sum(), "pct1", "PACS whose last entry is more than 180 days old", "Entries >180d / Total", 'DIVIDE(CALCULATE(SUM(gap_bands[pacs]), gap_bands[measure] = "Entry gap", gap_bands[band] IN {"181-365", ">365"}), CALCULATE(SUM(gap_bands[pacs]), gap_bands[measure] = "Entry gap"))', "Source tracker", "Collector, district cooperative bank", tone="bad")
k6 = P.kpi("Working PACS (3-Dec-2025)", 100 * wk.working.sum() / wk.total_pacs.sum(), "pct1", "PACS working on the ERP as reported in the 4-Dec review", "Working / Total", "DIVIDE(SUM(working_status_3dec2025[working]), SUM(working_status_3dec2025[total_pacs]))", "VC review deck 4-Dec-2025", "cooperative registrar, Collector", home=True)
k7 = P.kpi("Laggards: day-end on or before 31-Mar-2025", int(lg.dayend_on_or_before_31mar2025.sum()), "int", "PACS whose last day-end is 31-Mar-2025 or earlier (3-Dec)", "Sum of district counts", "SUM(laggards_3dec2025[dayend_on_or_before_31mar2025])", "VC review deck 4-Dec-2025", "Collector, district cooperative bank", tone="bad")
k8 = P.kpi("ERP go-live % (18-Sep-2025)", 100 * sd.golive.sum() / sd.total_pacs.sum(), "pct1", "PACS live on the ERP", "Go-live / Total", "DIVIDE(SUM(sep2025_district[golive]), SUM(sep2025_district[total_pacs]))", "Source tracker", "Minister, development finance partner")
k9 = P.kpi("Red PACS (health score < 40, 18-Sep-2025)", int(sd.red.sum()), "int", "PACS with an analyst health score below 40", "Count where score < 40", "SUM(sep2025_district[red])", "Source tracker", "cooperative registrar, Collector", tone="bad", note="score weights are an assumption")
k10 = P.kpi("Red Zone PACS (Nov-2025 list)", int(rz.red_zone_pacs.sum()), "int", "PACS on the Red Zone list for audit", "Rows in the list", "SUM(redzone_district[red_zone_pacs])", "Source tracker", "cooperative registrar, Audit dept", tone="bad")
for n, d, ds, gr in [("dayend_snapshots", sn, "State counts of current-day-end PACS at 10 snapshot dates", "snapshot date"), ("dayend_progress_district", dpd, "District day-end currency, first vs last snapshot", "district"), ("gap_district", gd, "Average entry and day-end gap by district, 6-Nov-2025", "district"), ("gap_bands", gb, "PACS by age band of last entry and last day-end", "measure x band"),
                     ("gap_groups", gg, "Average gaps by PACS group", "group"), ("sep2025_district", sd, "District KPI table, 18-Sep-2025 ERP entry status", "district"), ("sep2025_branch", sb, "district cooperative bank branch KPI table, 18-Sep-2025", "branch"), ("sep2025_bands", sbn, "Entry freshness bands, 18-Sep-2025", "band"),
                     ("working_status_3dec2025", wk, "Working vs not working PACS by district, 3-Dec-2025", "district"), ("laggards_3dec2025", lg, "Laggard PACS (entry and day-end on or before 31-Mar-2025) by district", "district"), ("dayend_month_3dec2025_district", mdm, "Month of last day-end by district, as on 3-Dec-2025", "district"),
                     ("dayend_month_3dec2025_state", mst, "State count of PACS by month of last day-end", "month"), ("redzone_district", rz, "Red Zone PACS by district", "district"), ("redzone_reasons", rzr, "Red Zone audit-pendency reasons, grouped", "reason")]: P.table(n, d, ds, gr)
P.relationships = ["Create `dim_district` (distinct district names from all district tables) and relate each `district` column to it (many-to-one, single direction).", "`sep2025_branch[district]` also relates to `dim_district`.", "`dayend_snapshots`, `gap_bands`, `gap_groups`, `sep2025_bands`, `dayend_month_3dec2025_state` and `redzone_reasons` are standalone state-level tables."]
P.sources = [("Operational status extracts (Excel)", "Day-end snapshots, entry and day-end gaps, district and branch KPI tables"), ("Review-meeting decks (PowerPoint)", "Working PACS, laggards, month of last day-end"), ("Audit Red Zone list (Excel)", "Red Zone counts and audit-pendency reasons, aggregated")]

P.exclusions = ["Real district, branch and bank names (replaced by pseudonyms).", "Original source files, PACS-level extracts, names, contact details and credentials.", "Real counts: all counts are rescaled, so absolute numbers are illustrative."]

P.assumptions = ["Current day-end: last day-end on or after 31-Mar-2025.", "Health score (0-100): go-live 25, day-end current 25, entry freshness 25, audit 10, YEP 5, HOC 5, T14 5. Weights are an analyst assumption; Red is below 40.", "Group names are as classified in the source trackers.", "Red Zone reasons are grouped by keyword from free text and are approximate."]

bandc = ["#2E8B57", "#9CCF6B", "#D99A00", "#E07B39", "#C0392B"]; gb_ = lambda m: [dict(label=r.band, value=int(r.pacs), color=bandc[i]) for i, r in enumerate(gb[gb.measure == m].itertuples())]
gm = gd.set_index("district"); dpd["pct"] = 100 * dpd.current / dpd.total
rows = dpd.join(gm[["avg_entry_gap", "avg_dayend_gap", "pct_entry_over_180"]], on="district").round(1).fillna("").to_dict("records")
P.page("status-nov2025", "Status: day-end and entry (Nov-2025)", "How many PACS have a current day-end, how fast it moved between 29-Sep and 5-Nov, and how old the last entries are.", [
    {"type": "kpis", "items": [k1, k2, k3, k4, k5]},
    {"type": "line", "title": "PACS with a current day-end, by snapshot", "w": "half", "src": "dayend_snapshots", "labels": [d[5:] for d in sn.date], "series": [dict(name="Current day-end", values=sn.current.tolist(), color=PALETTE[0]), dict(name="Day-end within 30 days", values=sn.within_30d.tolist(), color=PALETTE[1])]},
    {"type": "stacks", "title": "Age of last entry and last day-end (6-Nov)", "w": "half", "src": "gap_bands", "groups": [dict(name="Entry gap", parts=gb_("Entry gap")), dict(name="Day-end gap", parts=gb_("Day-end gap"))]},
    {"type": "hbars", "title": "Average day-end gap by group (days)", "w": "half", "src": "gap_groups", "rows": [dict(label=f"{r.group} ({int(r.pacs):,} PACS)", value=int(r.avg_dayend_gap), sub=f"entry {int(r.avg_entry_gap)}") for r in gg.itertuples()], "color": "var(--c3)"},
    {"type": "hbars", "title": "Ten districts with the longest day-end gap", "w": "half", "src": "gap_district", "rows": [dict(label=r.district, value=r.avg_dayend_gap) for r in gd.sort_values("avg_dayend_gap", ascending=False).head(10).itertuples()], "color": "var(--c3)", "fmt": "dec0"},
    {"type": "table", "title": "District table", "src": "dayend_progress_district", "search": "district", "cols": [dict(key="district", label="District"), dict(key="total", label="PACS", fmt="int"), dict(key="current", label="Current day-end", fmt="int"), dict(key="pct", label="Current %", fmt="pct1", heat=dict(lo=60, hi=85)), dict(key="gain", label="Gain since 29-Sep", fmt="signed"),
        dict(key="avg_dayend_gap", label="Avg day-end gap (d)", fmt="dec0"), dict(key="avg_entry_gap", label="Avg entry gap (d)", fmt="dec0"), dict(key="pct_entry_over_180", label="Entry >180d %", fmt="pct0", heat=dict(lo=0, hi=60, invert=True))], "rows": rows, "sort": "pct", "dir": 1}], tags=["cooperative registrar", "Collector", "development finance partner"])
P.page("working-dec2025", "Working PACS and laggards (3-Dec-2025)", "Which PACS are working on the ERP, which are laggards, and when each PACS last closed a day.", [
    {"type": "kpis", "items": [k6, k7, dict(label="Not working PACS", value=f"{int(wk.not_working.sum()):,}", tone="bad")]},
    {"type": "hbars", "title": "Lowest working-PACS % by district", "w": "half", "src": "working_status_3dec2025", "rows": [dict(label=r.district, value=r.working_pct) for r in wk.sort_values("working_pct").head(12).itertuples()], "fmt": "pct1", "max": 100, "color": "var(--c3)"},
    {"type": "hbars", "title": "PACS by month of last day-end (state)", "w": "half", "src": "dayend_month_3dec2025_state", "rows": [dict(label=r.period, value=int(r.pacs)) for r in mst.itertuples()], "color": "var(--c4)", "note": "Last day-end recorded for each PACS as on 3-Dec-2025."},
    {"type": "table", "title": "Working status and laggards by district", "src": "working_status_3dec2025", "search": "district", "cols": [dict(key="district", label="District"), dict(key="total_pacs", label="PACS", fmt="int"), dict(key="working", label="Working", fmt="int"), dict(key="not_working", label="Not working", fmt="int"), dict(key="working_pct", label="Working %", fmt="pct1", heat=dict(lo=50, hi=85)),
        dict(key="entry_old", label="Entry <= 31-Mar-25", fmt="int"), dict(key="dayend_old", label="Day-end <= 31-Mar-25", fmt="int")], "rows": wk.merge(lg.rename(columns={"entry_on_or_before_31mar2025": "entry_old", "dayend_on_or_before_31mar2025": "dayend_old"})[["district", "entry_old", "dayend_old"]], on="district", how="left").fillna(0).to_dict("records"), "sort": "working_pct", "dir": 1}], tags=["Collector", "district cooperative bank"])
sd["dayend_pct"] = 100 * sd.dayend_current / sd.total_pacs; sd["stale_pct"] = 100 * sd.stale_180d / sd.total_pacs; sd["golive_pct"] = 100 * sd.golive / sd.total_pacs; sb["dayend_pct"] = (100 * sb.dayend_current / sb.total_pacs).round(1)
P.page("league-sep2025", "District league and branches (Sep-2025)", "District league from the 18-Sep-2025 ERP status, with the district cooperative bank-branch table for drill-down.", [
    {"type": "kpis", "items": [k8, k9, dict(label="Stale PACS (no entry >180 days)", value=f"{int(sd.stale_180d.sum()):,}", tone="bad")]},
    {"type": "stack", "title": "Age of last entry (18-Sep-2025)", "w": "half", "src": "sep2025_bands", "parts": [dict(label=r.band, value=int(r.pacs), color=bandc[i]) for i, r in enumerate(sbn.itertuples())]},
    {"type": "hbars", "title": "Districts with the most Red PACS", "w": "half", "src": "sep2025_district", "rows": [dict(label=r.district, value=int(r.red)) for r in sd.sort_values("red", ascending=False).head(10).itertuples()], "color": "var(--c3)"},
    {"type": "table", "title": "District league", "src": "sep2025_district", "search": "district", "cols": [dict(key="district", label="District"), dict(key="total_pacs", label="PACS", fmt="int"), dict(key="golive_pct", label="Go-live %", fmt="pct1"), dict(key="dayend_pct", label="Day-end current %", fmt="pct1", heat=dict(lo=10, hi=50)), dict(key="entries_30d", label="Entry <=30d", fmt="int"), dict(key="stale_pct", label="Stale %", fmt="pct1", heat=dict(lo=0, hi=60, invert=True)), dict(key="audit_fy25", label="Audit FY25", fmt="int"), dict(key="hoc", label="HOC", fmt="int"), dict(key="red", label="Red PACS", fmt="int"), dict(key="avg_health", label="Health", fmt="dec1")], "rows": sd.round(1).to_dict("records"), "sort": "dayend_pct", "dir": 1},
    {"type": "table", "title": "district cooperative bank branch table", "src": "sep2025_branch", "search": "district", "maxh": 520, "cols": [dict(key="district", label="District"), dict(key="branch", label="Branch"), dict(key="total_pacs", label="PACS", fmt="int"), dict(key="dayend_current", label="Day-end current", fmt="int"), dict(key="dayend_pct", label="%", fmt="pct1"), dict(key="stale_180d", label="Stale", fmt="int"), dict(key="red", label="Red", fmt="int"), dict(key="avg_health", label="Health", fmt="dec1")], "rows": sb.to_dict("records"), "sort": "red"}], tags=["district cooperative bank", "Collector"])
P.page("redzone", "Red Zone PACS (Nov-2025 list)", "PACS on the Red Zone list for audit, by district, and why audit is pending. District totals only.", [
    {"type": "kpis", "items": [k10, dict(label="Districts on the list", value=str(len(rz))), dict(label="With audit and YEP completed", value=str(int(rzr[rzr.reason == "Audit and YEP completed"].pacs.sum())))]},
    {"type": "hbars", "title": "Red Zone PACS by district", "w": "half", "src": "redzone_district", "rows": [dict(label=r.district, value=int(r.red_zone_pacs)) for r in rz.sort_values("red_zone_pacs", ascending=False).itertuples()], "color": "var(--c3)"},
    {"type": "hbars", "title": "Reason for audit pendency (grouped)", "w": "half", "src": "redzone_reasons", "rows": [dict(label=r.reason, value=int(r.pacs)) for r in rzr.itertuples()], "color": "var(--c2)", "note": "Grouped by keyword from free-text reasons; approximate."},
    {"type": "table", "title": "District table", "src": "redzone_district", "cols": [dict(key="district", label="District"), dict(key="red_zone_pacs", label="Red Zone PACS", fmt="int"), dict(key="yep_completed", label="YEP completed", fmt="int"), dict(key="ready_audit_25mar", label="Ready for audit (25-Mar)", fmt="int"), dict(key="ready_audit_30mar", label="Ready for audit (30-Mar)", fmt="int"), dict(key="avg_vouchers", label="Avg vouchers", fmt="int")], "rows": rz.to_dict("records"), "sort": "red_zone_pacs"}], tags=["cooperative registrar", "Audit dept"])
P.build()
